#include <algorithm>
#include <functional>
#include <iomanip>
#include <iostream>

// 1. A template on a functor
struct Call {
    double operator()(double S, double K) const { return std::max(S - K, 0.0); }
};

template <typename Payoff>
double price(const Payoff& p, double S, double K) {
    return 0.5 * (p(S * 1.1, K) + p(S * 0.9, K));
}

// 2. A virtual call through a base class
struct PayoffBase {
    virtual ~PayoffBase() = default;
    virtual double operator()(double S, double K) const = 0;
};

struct CallV : PayoffBase {
    double operator()(double S, double K) const override { return std::max(S - K, 0.0); }
};

double price_virtual(const PayoffBase& p, double S, double K) {
    return 0.5 * (p(S * 1.1, K) + p(S * 0.9, K));
}

// 3. A function pointer
double call_payoff(double S, double K) { return std::max(S - K, 0.0); }

using PayoffPtr = double (*)(double, double);

double price_ptr(PayoffPtr p, double S, double K) {
    return 0.5 * (p(S * 1.1, K) + p(S * 0.9, K));
}

// 4. A std::function
using PayoffFn = std::function<double(double, double)>;

double price_function(const PayoffFn& p, double S, double K) {
    return 0.5 * (p(S * 1.1, K) + p(S * 0.9, K));
}

int main() {
    const double S = 100.0;
    const double K = 95.0;
    const CallV call_v{};
    const PayoffPtr call_ptr = call_payoff;
    PayoffFn call_fn;
    std::cout << std::boolalpha << "empty std::function: " << !call_fn << '\n';
    call_fn = Call{};

    std::cout << std::fixed << std::setprecision(4);
    std::cout << "template " << price(Call{}, S, K) << '\n';
    std::cout << "virtual  " << price_virtual(call_v, S, K) << '\n';
    std::cout << "pointer  " << price_ptr(call_ptr, S, K) << '\n';
    std::cout << "function " << price_function(call_fn, S, K) << '\n';
    call_fn = [](double S, double K) { return S > K ? 1.0 : 0.0; };
    std::cout << "function, now a digital " << price_function(call_fn, S, K) << '\n';
    return 0;
}

