struct Tick {
    int64_t ts_ns;          // nanoseconds since midnight
    double bid, ask;        // prices
    double bid_sz, ask_sz;  // sizes
};

struct Spec {
    std::string kind;
    double a = 0.0;
    double b = 0.0;
    double c = 0.0;
};

using Handler = std::function<double(const Tick&)>;

int main() {
    int n = 0;
    std::cin >> n;
    std::vector<Spec> specs(n);
    for (Spec& s : specs) {
        std::cin >> s.kind >> s.a;
        if (s.kind == "band") {
            std::cin >> s.b >> s.c;
        }
    }
    Tick tick{};
    std::cin >> tick.ts_ns >> tick.bid >> tick.ask >> tick.bid_sz >> tick.ask_sz;

    const long before = g_allocs;
    std::vector<Handler> handlers;
    handlers.reserve(specs.size());
    for (const Spec& s : specs) {
        if (s.kind == "spread") {
            const double w = s.a;
            handlers.push_back([w](const Tick& t) { return w * (t.ask - t.bid); });
        } else {
            const double lo = s.a;
            const double hi = s.b;
            const double w = s.c;
            handlers.push_back([lo, hi, w](const Tick& t) {
                const double mid = (t.bid + t.ask) / 2;
                return lo <= mid && mid <= hi ? w : 0.0;
            });
        }
    }
    std::cout << "allocations: " << g_allocs - before << '\n';
    double score = 0.0;
    for (const Handler& h : handlers) {
        score += h(tick);
