#include <cstddef>
#include <cstdint>
#include <cstdlib>
#include <iomanip>
#include <iostream>
#include <memory>
#include <new>
#include <variant>
#include <vector>

long g_allocs = 0;  // a minimal counting operator new
void* operator new(std::size_t n) {
    ++g_allocs;
    void* p = std::malloc(n);
    if (p == nullptr) {
        throw std::bad_alloc{};
    }
    return p;
}
void operator delete(void* p) noexcept { std::free(p); }
void operator delete(void* p, std::size_t) noexcept { std::free(p); }

struct MarketOrder { int64_t qty; };
struct LimitOrder { int64_t qty; double price; };
struct StopOrder { int64_t qty; double trigger; };
using Order = std::variant<MarketOrder, LimitOrder, StopOrder>;

// Quantity times the price each order would trade at.
struct Notional {
    double last;
    double operator()(const MarketOrder& o) const { return o.qty * last; }
    double operator()(const LimitOrder& o) const { return o.qty * o.price; }
    double operator()(const StopOrder& o) const { return o.qty * o.trigger; }
};

// A class hierarchy, only to compare the allocations.
struct OrderBase { virtual ~OrderBase() = default; };
struct LimitOrderV : OrderBase {
    int64_t qty = 0;
    double price = 0.0;
};

int main() {
    std::cout << "sizeof(Order) = " << sizeof(Order) << '\n';
    long before = g_allocs;
    std::vector<Order> orders;
    orders.reserve(1000);
    for (int i = 0; i < 1000; ++i) {
        if (i % 3 == 0) {
            orders.push_back(MarketOrder{10});
        } else if (i % 3 == 1) {
            orders.push_back(LimitOrder{5, 101.25});
        } else {
            orders.push_back(StopOrder{-5, 100.5});
        }
    }
    std::cout << "1000 variants: " << g_allocs - before << " allocation\n";

    before = g_allocs;
    std::vector<std::unique_ptr<OrderBase>> boxed;
    boxed.reserve(1000);
    for (int i = 0; i < 1000; ++i) {
        boxed.push_back(std::make_unique<LimitOrderV>());
    }
    std::cout << "1000 unique_ptrs: " << g_allocs - before << " allocations\n";

    double total = 0.0;
    for (const Order& o : orders) {
        total += std::visit(Notional{101.0}, o);
    }
    std::cout << std::fixed << std::setprecision(2) << "notional " << total << '\n';
    const LimitOrder* l = std::get_if<LimitOrder>(&orders[1]);
    std::cout << "orders[1] holds alternative " << orders[1].index() << ", price " << l->price << '\n';
    std::cout << "orders[0] holds a LimitOrder: " << std::boolalpha << (std::get_if<LimitOrder>(&orders[0]) != nullptr) << '\n';
    return 0;
}

