#include <cstddef>
#include <cstdint>
#include <cstdlib>
#include <iomanip>
#include <iostream>
#include <new>
#include <string>
#include <variant>
#include <vector>

long g_allocs = 0;  // a minimal counting operator new
void* operator new(std::size_t n) {
    ++g_allocs;
    void* p = std::malloc(n);
    if (p == nullptr) {
        throw std::bad_alloc{};
    }
    return p;
}
void operator delete(void* p) noexcept { std::free(p); }
void operator delete(void* p, std::size_t) noexcept { std::free(p); }

struct MarketOrder { int64_t qty; };
struct LimitOrder { int64_t qty; double price; };
struct StopOrder { int64_t qty; double trigger; };
using Order = std::variant<MarketOrder, LimitOrder, StopOrder>;

struct Notional {
    double last;
    double operator()(const MarketOrder& o) const { return o.qty * last; }
    double operator()(const LimitOrder& o) const { return o.qty * o.price; }
    double operator()(const StopOrder& o) const { return o.qty * o.trigger; }
};

struct Line { std::string kind; int64_t qty = 0; double px = 0.0; };

struct Describe {
    void operator()(const MarketOrder& o) const { std::cout << "market " << o.qty << '\n'; }
    void operator()(const LimitOrder& o) const { std::cout << "limit " << o.qty << " @ " << o.price << '\n'; }
    void operator()(const StopOrder& o) const { std::cout << "stop " << o.qty << " @ " << o.trigger << '\n'; }
};

int main() {
    double last = 0.0;
    int n = 0;
    std::cin >> last >> n;
    std::vector<Line> lines(n);
    for (Line& l : lines) {
        std::cin >> l.kind >> l.qty;
        if (l.kind != "market") {
            std::cin >> l.px;
        }
    }
    std::cout << std::fixed << std::setprecision(2);
    const long before = g_allocs;
    std::vector<Order> orders;
    orders.reserve(lines.size());
    for (const Line& l : lines) {
        if (l.kind == "market") {
            orders.push_back(MarketOrder{l.qty});
        } else if (l.kind == "limit") {
            orders.push_back(LimitOrder{l.qty, l.px});
        } else {
            orders.push_back(StopOrder{l.qty, l.px});
        }
    }
    double total = 0.0;
    for (const Order& o : orders) {
        std::visit(Describe{}, o);
        total += std::visit(Notional{last}, o);
    }
    std::cout << "allocations: " << g_allocs - before << '\n';
    std::cout << "notional " << total << '\n';
    return 0;
}
